type JsonOpeningDelimiter = "{" | "[";

type BalancedJsonFragment = {
  json: string;
  startIndex: number;
  endIndex: number;
};

function isJsonOpeningDelimiter(
  char: string | undefined,
  openers: readonly JsonOpeningDelimiter[],
): char is JsonOpeningDelimiter {
  return (char === "{" || char === "[") && openers.includes(char);
}

function extractBalancedJsonAt(
  raw: string,
  opts: { openers?: readonly JsonOpeningDelimiter[]; skipQuotedOpeners?: boolean },
  offset: number,
): BalancedJsonFragment | null {
  const openers = opts.openers ?? (["{", "["] as const);
  let start = offset;
  if (!opts.skipQuotedOpeners) {
    while (start < raw.length && !isJsonOpeningDelimiter(raw[start], openers)) {
      start += 1;
    }
  }
  const stack: JsonOpeningDelimiter[] = [];
  let inString = false;
  let escaped = false;
  for (let index = start; index < raw.length; index += 1) {
    const char = raw[index];
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
    } else if (char === '"') {
      inString = true;
    } else if (isJsonOpeningDelimiter(char, openers)) {
      if (stack.length === 0) {
        start = index;
      }
      stack.push(char);
    } else if (stack.length > 0 && char === (stack.at(-1) === "{" ? "}" : "]")) {
      stack.pop();
      if (stack.length === 0) {
        return { json: raw.slice(start, index + 1), startIndex: start, endIndex: index };
      }
    }
  }
  return null;
}

/** Extracts the first balanced JSON object/array from text. */
export function extractBalancedJsonPrefix(
  raw: string,
  opts: { openers?: readonly JsonOpeningDelimiter[]; skipQuotedOpeners?: boolean } = {},
): BalancedJsonFragment | null {
  return extractBalancedJsonAt(raw, opts, 0);
}

/** Extracts every balanced JSON object/array fragment from arbitrary text. */
export function extractBalancedJsonFragments(
  raw: string,
  opts: { openers?: readonly JsonOpeningDelimiter[]; skipQuotedOpeners?: boolean } = {},
): BalancedJsonFragment[] {
  const fragments: BalancedJsonFragment[] = [];
  for (let offset = 0; offset < raw.length;) {
    const fragment = extractBalancedJsonAt(raw, opts, offset);
    if (!fragment) {
      break;
    }
    fragments.push(fragment);
    offset = fragment.endIndex + 1;
  }
  return fragments;
}

/** Parses booleans and case-insensitive `true`/`false` string tokens. */
export function parseBoolean(value: unknown): boolean | undefined {
  if (typeof value === "boolean") {
    return value;
  }
  if (typeof value !== "string") {
    return undefined;
  }
  const normalized = value.trim().toLowerCase();
  if (normalized === "true") {
    return true;
  }
  if (normalized === "false") {
    return false;
  }
  return undefined;
}

/**
 * Shared CJK-aware character counting for approximate token estimates.
 *
 * This is a provider-independent budget heuristic, not an exact tokenizer.
 * Weighting common CJK, rare BMP characters, width-compatibility forms, and
 * supplementary ideographs separately keeps current tokenizers within a
 * conservative budget range while preserving the existing Latin behavior.
 */

export const CHARS_PER_TOKEN_ESTIMATE = 4;

export type StringCharBudgetOptions = { minimumRawWeight?: number };
const DEFAULT_BUDGET_OPTIONS: StringCharBudgetOptions = {};
const ASCII_RUN_OR_NON_ASCII_CODE_POINT_RE = /[\p{ASCII}]+|[^\p{ASCII}]/gu;

const WEIGHTED_CJK_RANGES = [
  [
    [0x00b7, 0x00b7],
    [0x3000, 0x319f],
    [0x4e00, 0x9fa5],
    [0xac00, 0xd7af],
    [0xff01, 0xff60],
  ],
  [
    [0x1100, 0x11ff],
    [0x2e80, 0x2fff],
    [0x31a0, 0x4dff],
    [0x9fa6, 0x9fff],
    [0xa000, 0xa4ff],
    [0xa700, 0xa707],
    [0xa960, 0xa97f],
    [0xd7b0, 0xd7ff],
    [0xf900, 0xfaff],
  ],
  [
    [0x02c7, 0x02c7],
    [0x02c9, 0x02cb],
    [0x02d9, 0x02d9],
    [0x02ea, 0x02eb],
    [0x0305, 0x0305],
    [0x0323, 0x0323],
    [0xfe10, 0xfe4f],
    [0xff61, 0xffdc],
    [0xffe0, 0xffe6],
  ],
  [[0x1d360, 0x1d371]],
  [
    [0x16fe0, 0x16fff],
    [0x1aff0, 0x1afff],
    [0x1b000, 0x1b16f],
    [0x1f200, 0x1f2ff],
    [0x20000, 0x2fa1f],
    [0x30000, 0x3347f],
  ],
] as const;

const WEIGHTED_CJK_RE = new RegExp(
  `[${WEIGHTED_CJK_RANGES.flatMap((ranges) =>
    ranges.map(([start, end]) => `\\u{${start.toString(16)}}-\\u{${end.toString(16)}}`),
  ).join("")}]`,
  "u",
);

// A fixed 205 KiB lookup avoids rescanning multilingual text for each weight.
const CJK_CATEGORY: Readonly<ArrayLike<number>> = (() => {
  const maxCodePoint = Math.max(
    ...WEIGHTED_CJK_RANGES.flatMap((ranges) => ranges.map(([, end]) => end)),
  );
  const categories = new Uint8Array(maxCodePoint + 1);
  for (const [bucket, ranges] of WEIGHTED_CJK_RANGES.entries()) {
    for (const [start, end] of ranges) {
      categories.fill(bucket + 1, start, end + 1);
    }
  }
  return categories;
})();

export function estimateStringChars(text: string): number {
  return estimateStringCharsWithMinimumRawWeight(text);
}

/** Apply a raw-text safety floor without multiplying CJK adjustments twice. */
export function estimateStringCharsWithMinimumRawWeight(
  text: string,
  options: StringCharBudgetOptions = DEFAULT_BUDGET_OPTIONS,
): number {
  const minimumRawWeight = Math.max(1, options.minimumRawWeight ?? 1);
  if (minimumRawWeight !== 1 && minimumRawWeight !== 2) {
    let chars = 0;
    // Other floors retain per-ASCII-run rounding and left-to-right numeric behavior.
    for (const match of text.matchAll(ASCII_RUN_OR_NON_ASCII_CODE_POINT_RE)) {
      const segment = match[0];
      const minimumChars = Math.ceil(segment.length * minimumRawWeight);
      chars +=
        segment.charCodeAt(0) <= 0x7f
          ? minimumChars
          : Math.max(estimateStringChars(segment), minimumChars);
    }
    return chars;
  }
  const firstWeighted = text.search(WEIGHTED_CJK_RE);
  if (firstWeighted < 0) {
    return text.length * minimumRawWeight;
  }
  let common = 0;
  let rareBmp = 0;
  let twoToken = 0;
  let threeTokenSupplementary = 0;
  let supplementary = 0;
  for (let index = firstWeighted; index < text.length; index += 1) {
    let codePoint = text.charCodeAt(index);
    if (codePoint < 0x80) {
      continue;
    }
    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
      const low = text.charCodeAt(index + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        codePoint = 0x10000 + (codePoint - 0xd800) * 0x400 + low - 0xdc00;
        index += 1;
      }
    }
    switch (CJK_CATEGORY[codePoint]) {
      case 1:
        common += 1;
        break;
      case 2:
        rareBmp += 1;
        break;
      case 3:
        twoToken += 1;
        break;
      case 4:
        threeTokenSupplementary += 1;
        break;
      case 5:
        supplementary += 1;
        break;
      default:
        break;
    }
  }
  const commonEstimate =
    text.length * minimumRawWeight + common * (CHARS_PER_TOKEN_ESTIMATE - minimumRawWeight);
  return (
    commonEstimate +
    rareBmp * (CHARS_PER_TOKEN_ESTIMATE * 3 - minimumRawWeight) +
    twoToken * (CHARS_PER_TOKEN_ESTIMATE * 2 - minimumRawWeight) +
    threeTokenSupplementary * (CHARS_PER_TOKEN_ESTIMATE * 3 - 2 * minimumRawWeight) +
    supplementary * (CHARS_PER_TOKEN_ESTIMATE * 4 - 2 * minimumRawWeight)
  );
}

export function estimateTokensFromChars(chars: number): number {
  return Math.ceil(Math.max(0, chars) / CHARS_PER_TOKEN_ESTIMATE);
}

/** Truncates to a nonnegative code-point budget; grapheme clusters may be split. */
export function truncateCodePoints(text: string, maxCodePoints: number): string {
  const limit = Math.max(0, Math.trunc(maxCodePoints) || 0);
  if (text.length <= limit) {
    return text;
  }
  const prefix: string[] = [];
  // Join only the bounded prefix; a substring can retain the entire oversized input.
  for (const codePoint of text) {
    if (prefix.length >= limit) {
      break;
    }
    prefix.push(codePoint);
  }
  return prefix.join("");
}

// Structural formatting stays policy-free; diagnostic adapters supply their redaction policy.
export type FormatErrorMessageOptions = {
  includeCode?: boolean;
  redact?: (text: string) => string;
};

const STRUCTURED_ERROR_OWNED_FIELDS = new Set(["cause", "message", "name", "stack"]);
const STRUCTURED_ERROR_PROTOTYPE_FIELDS = new Set(["__proto__", "constructor", "prototype"]);
const PROVIDER_AUTH_PERSISTENCE_ERROR_BRAND = Symbol.for(
  "openclaw.provider-auth-persistence-error",
);

export class ProviderAuthPersistenceError extends AggregateError {
  readonly [PROVIDER_AUTH_PERSISTENCE_ERROR_BRAND] = true;
  readonly persistenceError: unknown;
  readonly cleanupError: unknown;

  constructor(message: string, persistenceError: unknown, { cause }: { cause: unknown }) {
    super([persistenceError, cause], message, { cause });
    this.persistenceError = persistenceError;
    this.cleanupError = cause;
  }
}

function isProviderAuthPersistenceError(value: Error): value is ProviderAuthPersistenceError {
  try {
    return (
      PROVIDER_AUTH_PERSISTENCE_ERROR_BRAND in value &&
      value[PROVIDER_AUTH_PERSISTENCE_ERROR_BRAND] === true
    );
  } catch {
    return false;
  }
}

function isErrorObject(value: unknown): value is Error {
  try {
    if (value instanceof Error) {
      return true;
    }
    // VM and worker realms have distinct Error constructors; retain their diagnostic fields.
    return Object.prototype.toString.call(value) === "[object Error]";
  } catch {
    return false;
  }
}

function isAggregateErrorObject(error: Error): boolean {
  try {
    if (error instanceof AggregateError) {
      return true;
    }
    for (let proto = Object.getPrototypeOf(error); proto; proto = Object.getPrototypeOf(proto)) {
      const constructor: unknown = Object.getOwnPropertyDescriptor(proto, "constructor")?.value;
      if (typeof constructor === "function" && constructor.name === "AggregateError") {
        return true;
      }
    }
  } catch {
    // An opaque prototype must not promote arbitrary errors-array metadata into causes.
  }
  return false;
}

function readProperty(value: object, key: string): unknown {
  try {
    return (value as Record<string, unknown>)[key];
  } catch {
    return undefined;
  }
}

function readErrorText(value: object, key: "message" | "name"): string | undefined {
  const field = readProperty(value, key);
  return typeof field === "string" ? field : undefined;
}

function formatStatusAndCode(value: unknown): string | undefined {
  if ((typeof value !== "object" || value === null) && typeof value !== "function") {
    return undefined;
  }
  try {
    if (Object.keys(value).some((key) => key !== "status" && key !== "code")) {
      return undefined;
    }
  } catch {
    // Proxy enumeration can fail; retain the safe status/code fallback below.
  }
  const statusValue = readProperty(value, "status");
  const codeValue = readProperty(value, "code");
  if (statusValue === undefined && codeValue === undefined) {
    return undefined;
  }
  const statusText =
    typeof statusValue === "string" || typeof statusValue === "number"
      ? String(statusValue)
      : "unknown";
  const codeText =
    typeof codeValue === "string" || typeof codeValue === "number" ? String(codeValue) : "unknown";
  return `status=${statusText} code=${codeText}`;
}

function stringifyUnknown(value: unknown): string {
  if (value === null || (typeof value !== "object" && typeof value !== "function")) {
    return String(value);
  }
  try {
    const json = JSON.stringify(value);
    if (json !== undefined) {
      return json;
    }
  } catch {
    // Fall through to the stable object tag below.
  }
  try {
    return Object.prototype.toString.call(value);
  } catch {
    return "Unknown error";
  }
}

export function readErrorCauses(current: Record<string, unknown>): unknown[] {
  if (!isErrorObject(current)) {
    return [];
  }
  const cause = readProperty(current, "cause");
  const errors = isAggregateErrorObject(current) ? readProperty(current, "errors") : undefined;
  // Cleanup is the native cause; keep initiating failures first in operator diagnostics.
  const persistenceFailures = isProviderAuthPersistenceError(current)
    ? [readProperty(current, "persistenceError"), readProperty(current, "cleanupError")]
    : [];
  // Downlevel await-using emits a named Error; both failure fields exist even for nullish throws.
  const suppressed =
    readErrorText(current, "name") === "SuppressedError"
      ? [readProperty(current, "error"), readProperty(current, "suppressed")].map((failure) =>
          failure == null ? String(failure) : failure,
        )
      : [];
  return [
    ...persistenceFailures,
    cause || undefined,
    ...(Array.isArray(errors) ? errors : []),
    ...suppressed,
  ];
}

/** Formats unknown errors with cause/aggregate details and optional diagnostic redaction. */
export function formatErrorMessage(
  value: unknown,
  options: FormatErrorMessageOptions = {},
): string {
  let formatted: string;
  if (isErrorObject(value)) {
    formatted = readErrorText(value, "message") || readErrorText(value, "name") || "Error";
    const seenMessages = new Set<string>([formatted]);
    const appendCauseMessage = (message: string | undefined): void => {
      if (!message || seenMessages.has(message)) {
        return;
      }
      formatted += ` | ${message}`;
      seenMessages.add(message);
    };
    if (options.includeCode) {
      const code = readProperty(value, "code");
      if (typeof code === "string" || typeof code === "number") {
        appendCauseMessage(String(code));
      }
    }
    const causes = collectErrorGraphCandidates(value, readErrorCauses);
    for (const cause of causes.slice(1)) {
      if (isErrorObject(cause)) {
        const message = readErrorText(cause, "message");
        // Wrappers may already embed the cause message; codes remain separate below.
        if (message && formatted.includes(message)) {
          seenMessages.add(message);
        } else {
          appendCauseMessage(message);
        }
        const code = readProperty(cause, "code");
        if (typeof code === "string" || typeof code === "number") {
          appendCauseMessage(String(code));
        }
      } else if (typeof cause === "string") {
        appendCauseMessage(cause);
      } else {
        appendCauseMessage(formatStatusAndCode(cause) ?? stringifyUnknown(cause));
      }
    }
  } else {
    formatted = formatStatusAndCode(value) ?? stringifyUnknown(value);
  }
  return options.redact ? options.redact(formatted) : formatted;
}

/**
 * Formats an error's stack so it always names the error. Bun can materialize
 * `stack` during garbage collection with a bare `Error` header, dropping the
 * message that V8-style stacks carry.
 */
export function formatErrorStackWithMessage(error: Error): string {
  const name = readErrorText(error, "name") || "Error";
  const message = readErrorText(error, "message") ?? "";
  const stack = readProperty(error, "stack");
  if (typeof stack !== "string" || !stack) {
    return message || name;
  }
  if (!message || stack.includes(message)) {
    return stack;
  }
  const header = `${name}: ${message}`;
  const lineEnd = stack.indexOf("\n");
  const firstLine = lineEnd < 0 ? stack : stack.slice(0, lineEnd);
  return firstLine === name ? header + stack.slice(firstLine.length) : `${header}\n${stack}`;
}

/**
 * Normalizes an unknown thrown value into an Error. Non-Error objects become
 * the `cause` and have their enumerable fields copied so structured details
 * (codes, statuses) survive the coercion.
 */
export function toErrorObject(value: unknown, fallbackMessage: string): Error {
  if (value instanceof Error) {
    return value;
  }
  if (typeof value === "string") {
    return new Error(value);
  }
  const error = new Error(fallbackMessage, { cause: value });
  if ((typeof value === "object" && value !== null) || typeof value === "function") {
    Object.assign(error, value);
  }
  return error;
}

/** Preserves structured details while isolating hostile object field access. */
export function toStructuredErrorObject(value: unknown): Error {
  if (value instanceof Error) {
    return value;
  }
  const message = String(value);
  if ((typeof value !== "object" || value === null) && typeof value !== "function") {
    return toErrorObject(value, message);
  }
  const error = new Error(message, { cause: value });
  try {
    const detailKeys = Reflect.ownKeys(value).filter(
      (key) =>
        (typeof key !== "string" ||
          (!STRUCTURED_ERROR_OWNED_FIELDS.has(key) &&
            !STRUCTURED_ERROR_PROTOTYPE_FIELDS.has(key))) &&
        Reflect.getOwnPropertyDescriptor(value, key)?.enumerable,
    );
    for (const key of detailKeys) {
      try {
        Object.defineProperty(error, key, {
          value: Reflect.get(value, key),
          writable: true,
          enumerable: true,
          configurable: true,
        });
      } catch {
        // Skip fields whose getters or property definitions reject access.
      }
    }
  } catch {
    // Opaque proxies may reject enumeration; preserve the original failure as the cause.
  }
  return error;
}

/** Preserves Error values and stringifies every other value into a new Error. */
export function toStringifiedError(value: unknown): Error {
  return value instanceof Error ? value : new Error(String(value));
}

/** Reads Error messages unchanged and stringifies every other value. */
export function coerceErrorMessage(value: unknown): string {
  return value instanceof Error ? value.message : String(value);
}

/** Renders a non-Error cause as useful text without throwing. */
export function stringifyNonErrorCause(value: unknown): string {
  if (value === null) {
    return "null";
  }
  if (typeof value === "string") {
    return value;
  }
  if (typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") {
    return String(value);
  }
  try {
    return JSON.stringify(value) ?? Object.prototype.toString.call(value);
  } catch {
    return Object.prototype.toString.call(value);
  }
}

/** Renders an error and up to eight causes without choosing log formatting or redaction. */
export function mapErrorCauseChain(error: Error, renderError: (error: Error) => string): string[] {
  const segments = [renderError(error)];
  let current: unknown = error.cause;
  let depth = 0;
  while (current !== undefined && current !== null && depth < 8) {
    if (current instanceof Error) {
      segments.push(renderError(current));
      current = current.cause;
    } else {
      segments.push(stringifyNonErrorCause(current));
      current = undefined;
    }
    depth += 1;
  }
  return segments;
}

export function extractErrorCode(err: unknown): string | undefined {
  if (!err || typeof err !== "object") {
    return undefined;
  }
  const code = readProperty(err, "code");
  return typeof code === "string" || typeof code === "number" ? String(code) : undefined;
}

export function readErrorName(err: unknown): string {
  if (!err || typeof err !== "object") {
    return "";
  }
  // SAFETY: Object-shaped error wrappers may omit name or supply a non-string value.
  const name = (err as { name?: unknown }).name;
  return typeof name === "string" ? name : "";
}

export function collectErrorGraphCandidates(
  err: unknown,
  resolveNested?: (current: Record<string, unknown>) => Iterable<unknown>,
): unknown[] {
  if (err == null) {
    return [];
  }
  const candidates: unknown[] = [err];
  const seen = new Set<unknown>().add(err);

  // First discovery fixes breadth-first order; the returned array is also the worklist.
  for (const current of candidates) {
    if (!current || typeof current !== "object" || !resolveNested) {
      continue;
    }
    // SAFETY: Non-object nodes were excluded before the callback reads optional graph links.
    for (const nested of resolveNested(current as Record<string, unknown>)) {
      if (nested != null && !seen.has(nested)) {
        seen.add(nested);
        candidates.push(nested);
      }
    }
  }

  return candidates;
}

export function extractErrorCodeOrErrno(err: unknown): string | undefined {
  const code = extractErrorCode(err);
  if (code) {
    return code.trim().toUpperCase();
  }
  if (!err || typeof err !== "object") {
    return undefined;
  }
  // SAFETY: The object guard permits the optional errno field used by SDK wrappers.
  const errno = (err as { errno?: unknown }).errno;
  if (typeof errno === "string" && errno.trim()) {
    return errno.trim().toUpperCase();
  }
  if (typeof errno === "number" && Number.isFinite(errno)) {
    return String(errno);
  }
  return undefined;
}

export function collectNestedErrorCandidates(err: unknown): unknown[] {
  return collectErrorGraphCandidates(err, (current) => {
    const nested: unknown[] = [
      readProperty(current, "cause"),
      readProperty(current, "reason"),
      readProperty(current, "original"),
      readProperty(current, "error"),
      readProperty(current, "suppressed"),
      readProperty(current, "data"),
    ];
    const errors = readProperty(current, "errors");
    if (Array.isArray(errors)) {
      nested.push(...errors);
    }
    return nested;
  });
}

/** Returns the value or throws with the named context; use for genuine invariants only. */
export function expectDefined<T>(value: T | null | undefined, context: string): T {
  if (value === null || value === undefined) {
    throw new Error("expected " + context + " to be defined");
  }
  return value;
}

import { expectDefined } from "./expect.js";

type ByteSizeUnit = "byte" | "kilo" | "mega" | "giga" | "tera";
type ByteSizeStyle = "iec" | "legacy-binary";

type ByteSizeFormatOptions = {
  style: ByteSizeStyle;
  maxUnit: ByteSizeUnit;
  separator: "" | " ";
  fractionDigits: number | ((value: number, unit: ByteSizeUnit) => number | null);
  floorUnits?: readonly ByteSizeUnit[];
};

const BYTE_SIZE_UNITS: readonly ByteSizeUnit[] = ["byte", "kilo", "mega", "giga", "tera"];
const BYTE_SIZE_STYLES = {
  iec: { base: 1024, labels: ["B", "KiB", "MiB", "GiB", "TiB"] },
  "legacy-binary": { base: 1024, labels: ["B", "KB", "MB", "GB", "TB"] },
} as const satisfies Record<ByteSizeStyle, { base: number; labels: readonly string[] }>;

export type RelativeTimeUnit = "second" | "minute" | "hour" | "day";

/** Buckets an absolute duration while preserving nested display rounding at unit boundaries. */
export function bucketRelativeTimeMs(durationMs: number): {
  value: number;
  unit: RelativeTimeUnit;
} {
  const seconds = Math.round(durationMs / 1000);
  if (seconds < 60) {
    return { value: seconds, unit: "second" };
  }
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) {
    return { value: minutes, unit: "minute" };
  }
  const hours = Math.round(minutes / 60);
  return hours < 48
    ? { value: hours, unit: "hour" }
    : { value: Math.round(hours / 24), unit: "day" };
}

/** Formats a byte count with caller-explicit scale, labels, precision, and unit cap. */
export function formatByteSize(bytes: number, options: ByteSizeFormatOptions): string {
  const { base, labels } = BYTE_SIZE_STYLES[options.style];
  const maxUnitIndex = BYTE_SIZE_UNITS.indexOf(options.maxUnit);
  let unitIndex = 0;
  let value = bytes;
  while (value >= base && unitIndex < maxUnitIndex) {
    value /= base;
    unitIndex += 1;
  }

  const unit = expectDefined(BYTE_SIZE_UNITS[unitIndex], "byte-size unit");
  const label = expectDefined(labels[unitIndex], "byte-size label");
  const fractionDigits =
    typeof options.fractionDigits === "function"
      ? options.fractionDigits(value, unit)
      : options.fractionDigits;
  if (fractionDigits === null) {
    return `${value}${options.separator}${label}`;
  }
  if (options.floorUnits?.includes(unit)) {
    value = Math.floor(value * 10 ** fractionDigits) / 10 ** fractionDigits;
  }
  return `${value.toFixed(fractionDigits)}${options.separator}${label}`;
}

/** Formats token units while callers retain input validation and whole-token rounding. */
export function formatCompactTokenCount(
  tokens: number,
  options: {
    thousandsPrecision?: 0 | 1;
    thousandsSuffix?: string;
    millionsSuffix?: string;
    trimTrailingZero?: boolean;
    maxUnit?: "million" | "billion";
  } = {},
): string {
  if (tokens < 1_000) {
    return String(Math.round(tokens));
  }
  const trim = (value: string) => (options.trimTrailingZero ? value.replace(/\.0$/, "") : value);
  // Billion presentation is based on the count, not rounded millions.
  if (options.maxUnit === "billion" && tokens >= 1_000_000_000) {
    return `${trim((tokens / 1_000_000_000).toFixed(1))}B`;
  }
  if (tokens < 1_000_000) {
    const thousands = (tokens / 1_000).toFixed(options.thousandsPrecision ?? 1);
    if (Number(thousands) < 1_000) {
      return `${trim(thousands)}${options.thousandsSuffix ?? "k"}`;
    }
  }
  return `${trim((tokens / 1_000_000).toFixed(1))}${options.millionsSuffix ?? "m"}`;
}

