    if (done) {
      return { size, truncated: false };
    }
    if (options.skipEmptyChunks !== false && !value?.length) {
      continue;
    }
    const remaining = options.maxBytes - size;
    size += value.length;
    if (size > options.maxBytes || (options.stopAtLimit && size === options.maxBytes)) {
      if (remaining > 0) {
